import{_ as i,c as a,o as t,a6 as e}from"./chunks/framework.Banfyh_6.js";const r=JSON.parse('{"title":"Linux 网络传输工具：curl VS wget","description":"在Linux命令行下载文件时，curl和wget是两个常用的工具。尽管它们在某些功能上相似，但它们在设计和使用场景上有所不同。","frontmatter":{"title":"Linux 网络传输工具：curl VS wget","description":"在Linux命令行下载文件时，curl和wget是两个常用的工具。尽管它们在某些功能上相似，但它们在设计和使用场景上有所不同。","categories":["工具分享"],"tags":["Linux","运维"],"outline":[2,3],"date":"2025-02-13T17:30:00.000Z","head":[["meta",{"name":"keywords","content":"Linux, 运维, curl, wget, 网络传输, 网络工具"}]]},"headers":[],"relativePath":"training/linux/curl-wget.md","filePath":"training/linux/curl-wget.md","lastUpdated":1739438035000}'),p={name:"training/linux/curl-wget.md"};function l(n,s,h,d,c,o){return t(),a("div",{"data-pagefind-body":!0},s[0]||(s[0]=[e(`<h1 id="linux-网络传输工具-curl-vs-wget" tabindex="-1">Linux 网络传输工具：curl VS wget <a class="header-anchor" href="#linux-网络传输工具-curl-vs-wget" aria-label="Permalink to &quot;Linux 网络传输工具：curl VS wget&quot;">​</a></h1><p>在Linux系统下载文件过程中，经常会用到 <code>wget</code> 和 <code>curl</code>，一般都是想起哪个用哪个。经过尝试，总感觉 curl 的功能要更加强大一些。通常，通过链接下载一个文件，以下两个命令都适用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/file.f</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/file.f</span></span></code></pre></div><p>但是我的使用习惯中，wget 通常下载一些简单的文件，而 curl 则经常被用来判断网页是否可以访问。因为 wget 请求网页需要下载到本地再打开。</p><p>事实上，他们都是功能强大的网络数据传输工具，虽然在某些功能上有所重叠，但是其设计理念、 功能特点以及适用场景存在显著差异。本文将详细解析这两个工具的命令用法，探讨它们的共同点以及各自的特点。</p><h2 id="一、wget-简介" tabindex="-1">一、wget 简介 <a class="header-anchor" href="#一、wget-简介" aria-label="Permalink to &quot;一、wget 简介&quot;">​</a></h2><p><code>wget</code> 通常用来从网络上下载静态资源，支持 http、https、ftp 协议，是比较常用的文件下载工具。</p><p><code>wget</code> 最简单的用法就是从指定的 URL 下载静态资源，例如，以下命令即可下载本站 LOGO 图片，并默认保存在当前目录，文件名与 URL 中文件名同名：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.imufeng.cn/logo.svg</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>如果请求路径中存在参数，保存到本地的文件名也会将参数保留，可能会导致文件无法访问。比如这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@imufeng.cn ~]# wget www.imufeng.cn/logo.svg?param=123</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[root@imufeng.cn ~]# ls</span></span>
<span class="line"><span>&#39;logo.svg?param=123&#39;</span></span></code></pre></div></div><p>上边这种情况就需要在保存的时候修改名称了，以下列出 wget 常用的一些参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>-O</code> 或 <code>--output-document</code></td><td>指定保存路径及文件名</td></tr><tr><td><code>-P</code> 或 <code>--directory-prefix </code></td><td>指定保存路径，文件名不变</td></tr><tr><td><code>-r</code> 或 <code>--recursive</code></td><td>启用递归下载，可以下载整个网站内容</td></tr><tr><td><code>-l</code> 或 <code>--level</code></td><td>限制递归下载深度</td></tr><tr><td><code>--exclude-directories</code></td><td>指定递归下载时需要排除的目录</td></tr><tr><td><code>-c</code> 或 <code>--continue</code></td><td>启用断点续传</td></tr><tr><td><code>-b</code> 或 <code>--background</code></td><td>后台下载</td></tr><tr><td><code>--limit-rate</code></td><td>限制下载速度，如 <code>--limit-rate=100k</code></td></tr><tr><td><code>--timeout</code></td><td>设置连接超时时间</td></tr><tr><td><code>--wait</code></td><td>设置多个请求之间的等待时间</td></tr><tr><td><code>--header</code></td><td>设置请求头</td></tr><tr><td><code>-S</code> 或 <code>--server-response</code></td><td>显示服务器响应头信息</td></tr></tbody></table><h2 id="二、curl-简介" tabindex="-1">二、curl 简介 <a class="header-anchor" href="#二、curl-简介" aria-label="Permalink to &quot;二、curl 简介&quot;">​</a></h2><p>curl 是一个极为强大的多功能网络传输工具，支持多种网络协议，包括 HTTP、HTTPS、FTP、SFTP、SMTP、POP3、IMAP 等，这使得 curl 不仅可以用于下载文件，还可以用于发送电子邮件、处理邮件协议、与 Web API 进行交互等复杂任务。下载文件只是其最基础的用法。</p><p>curl 支持多种请求方式，如 GET、POST、PUT、DELETE 等。用户可以通过指定不同的请求方法和参数，向服务器发送复杂的请求。例如，使用 curl -X POST 可以发送 POST 请求，而 curl -X PUT 则用于发送 PUT 请求。这种灵活性使得 curl 在开发和测试 Web 应用程序时非常有用。</p><p>比如，我们可以通过以下方法向指定 URL 发送 PUT 或 DELETE 请求：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;id=1&amp;name=mufeng&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mufeng.dev/user/update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mufeng.dev/user/delete/1</span></span></code></pre></div><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><ol><li><p>发送 GET 请求</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p>从 <code>http://example.com</code> 获取数据并输出到<strong>标准输出</strong>。</p></li><li><p>保存相应内容</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p><code>-o output.txt</code> ：将响应内容保存到 <code>output.txt</code> 文件中。</p></li><li><p>显示响应头信息</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p><code>-i</code> ：显示响应头信息和响应体。或者将响应头信息保存到文件中：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headers.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p><code>-D headers.txt</code>：将响应头信息保存到 <code>headers.txt</code> 文件中。</p></li><li><p>发送带请求体的请求</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;param1=value1&amp;param2=value2&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/form</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;:&quot;John&quot;,&quot;age&quot;:20}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/api</span></span></code></pre></div><p><code>-X POST</code>：指定请求方法为 POST。</p><p><code> -H &quot;Content-Type: application/json&quot;</code>：设置请求头，指定内容类型为 JSON。</p><p><code>-d</code> ：指定要发送的数据。</p></li><li><p>认证鉴权</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> username:password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div></li><li><p>处理 Cookie</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cookies.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cookies.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p><code>-c cookies.txt</code>：将服务器返回的 Cookie 保存到 <code>cookies.txt</code> 文件中。</p><p><code>-b cookies.txt</code>：从 <code>cookies.txt</code> 文件中读取 Cookie 并发送给服务器。</p></li><li><p>设置连接超时时间</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --connect-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-time</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p><code>--connect-timeout 30</code>：设置连接超时时间为 30 秒。</p><p><code>--max-time 60</code>：设置最大超时时间为 60 秒。</p></li><li><p>使用代理服务器</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://proxy.example.com:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div></li><li><p>限制下载速度</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit-rate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 100k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/file.zip</span></span></code></pre></div></li><li><p>详细模式</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com</span></span></code></pre></div><p>详细模式可以查看请求和响应的头信息。</p></li><li><p>并发模式</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/resource1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://example.com/resource2</span></span></code></pre></div></li></ol><h2 id="三、区别" tabindex="-1">三、区别 <a class="header-anchor" href="#三、区别" aria-label="Permalink to &quot;三、区别&quot;">​</a></h2><p>虽然我们经常使用 <code>curl</code> 和 <code>wget</code> 命令从网站上下载资源，这也只是他们功能重叠的一部分，他们的设计理念、功能特点及适用场景存在显著差异。</p><p><code>curl</code> 更加专注于网络传输，通常使用其进行 API 接口的调用测试，它能够支持各种复杂的请求，例如发送 JSON 数据或处理表单数据。它还支持多种认证方式，能够处理 cookie 信息，从而模拟浏览器的行为。这些特性使得他成为开发人员和系统管理员在进行网络交互、测试 Web API、处理认证和并发请求时的首选工具。</p><p>相比之下，<code>wget</code> 更加注重文件下载，它的核心功能就是通过 HTTP、FTP 等协议下载静态资源，支持断点续传、支持递归下载、后台下载等。对于网站的备份、批量下载等十分有用。尽管它对于 WEB 请求的支持有限，但是已经可以满足绝大多数的文件下载需求。</p><p>综上，<code>curl</code> 更加偏向于 WEB API 交互、发送多种类型的请求以及处理认证等，而 <code>wget</code> 更适合下载文件，简单易用且高效。总之，<code>curl</code> 和 <code>wget</code> 各有优势，它们在 Linux 系统中都扮演着重要的角色。通过合理选择和使用这两个工具，用户可以更高效地完成各种网络任务。了解它们的特点和功能，能够帮助用户根据具体需求选择最合适的工具，从而提高工作效率和任务完成的质量。</p>`,24)]))}const g=i(p,[["render",l]]);export{r as __pageData,g as default};
